    @EventHandler( payloadType=CreateModelEvent.class )
    public void handle( CreateModelEvent event) {
	    LOGGER.info("handling CreateModelEvent - " + event );
	    Model entity = new Model();
            entity.setModelId( event.getModelId() );
            entity.setName( event.getName() );
            entity.setTaskDescription( event.getTaskDescription() );
            entity.setModelType( event.getModelType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllModel( entity );
    }

