    /**
     * Method to retrieve the Model via an ModelPrimaryKey.
     * @param 	id Long
     * @return 	Model
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Model handle( FindModelQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getModelId() );
    }
    
    /**
     * Method to retrieve a collection of all Models
     *
     * @param	query	FindAllModelQuery 
     * @return 	List<Model> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Model> handle( FindAllModelQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindModel,
 * but only if the id matches
 *
 * @param		entity	Model
 */
	protected void emitFindModel( Model entity ) {
		LOGGER.info("handling emitFindModel" );
		
	    queryUpdateEmitter.emit(FindModelQuery.class,
	                            query -> query.getFilter().getModelId().equals(entity.getModelId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllModel
	 * 
	 * @param		entity	Model
	 */
	protected void emitFindAllModel( Model entity ) {
		LOGGER.info("handling emitFindAllModel" );
		
	    queryUpdateEmitter.emit(FindAllModelQuery.class,
	                            query -> true,
	                            entity);
	}

